import{_ as e,c as t,o as i,a2 as a}from"./chunks/framework._4mWlOLd.js";const s=JSON.parse('{"title":"Findings - Cost Analysis","description":"","frontmatter":{"layout":"doc","title":"Findings - Cost Analysis"},"headers":[],"relativePath":"docs/quicklinker-zeroRPM/findings/cost-analysis.md","filePath":"docs/quicklinker-zeroRPM/findings/cost-analysis.md","lastUpdated":1741723016000}');const o=e({name:"docs/quicklinker-zeroRPM/findings/cost-analysis.md"},[["render",function(e,s,o,n,r,l){return i(),t("div",null,s[0]||(s[0]=[a('<h1 id="findings-cost-analysis" tabindex="-1">Findings: Cost Analysis <a class="header-anchor" href="#findings-cost-analysis" aria-label="Permalink to &quot;Findings: Cost Analysis&quot;">​</a></h1><p>QuickLinker-ZeroRPM targets <strong>$0/month infrastructure costs</strong> while handling 100,000 requests per minute (RPM). This analysis evaluates how the project achieves that, focusing on database choices (SQLite, PostgreSQL, MongoDB), hosting on Oracle’s Always Free Tier, and workload optimization with Redis caching. The findings validate the cost-efficiency goal and highlight trade-offs that make this possible.</p><h2 id="hosting-oracle-always-free-tier" tabindex="-1">Hosting: Oracle Always Free Tier <a class="header-anchor" href="#hosting-oracle-always-free-tier" aria-label="Permalink to &quot;Hosting: Oracle Always Free Tier&quot;">​</a></h2><h3 id="specs-and-capabilities" tabindex="-1">Specs and Capabilities <a class="header-anchor" href="#specs-and-capabilities" aria-label="Permalink to &quot;Specs and Capabilities&quot;">​</a></h3><ul><li><strong>Compute</strong>: 4 Arm cores, 24 GB RAM, 200 GB block storage.</li><li><strong>Bandwidth</strong>: 4 Gbps outbound, far exceeding the estimated 13.33 Mbps needed for 100,000 RPM (assuming 1 KB/request: 100,000 req/min × 1 KB × 8 bits ÷ 60 sec ≈ 13.33 Mbps).</li><li><strong>Cost</strong>: $0/month, with no hidden fees for the base tier (<a href="https://www.oracle.com/in/cloud/free/faq/" target="_blank" rel="noreferrer">Oracle Free Tier FAQ</a>).</li></ul><h3 id="fit-for-purpose" tabindex="-1">Fit for Purpose <a class="header-anchor" href="#fit-for-purpose" aria-label="Permalink to &quot;Fit for Purpose&quot;">​</a></h3><ul><li>A single VM comfortably runs Node.js, Express, Redis, and SQLite, with room for LiteFS replication in Phase 3.</li><li>Users report hosting full stacks (e.g., web servers, databases) on this tier without throttling, confirming its viability (<a href="https://www.reddit.com/r/selfhosted/comments/15q1o59/is_oracle_cloud_free_tier_actually_free_tier/" target="_blank" rel="noreferrer">Reddit Discussion</a>).</li><li>No need for paid upgrades—24 GB RAM and 4 cores exceed the lightweight stack’s needs, even at peak load.</li></ul><h3 id="cost-implication" tabindex="-1">Cost Implication <a class="header-anchor" href="#cost-implication" aria-label="Permalink to &quot;Cost Implication&quot;">​</a></h3><p>Oracle’s free tier eliminates hosting expenses, shifting the burden to software optimization for cost efficiency.</p><h2 id="database-cost-breakdown" tabindex="-1">Database Cost Breakdown <a class="header-anchor" href="#database-cost-breakdown" aria-label="Permalink to &quot;Database Cost Breakdown&quot;">​</a></h2><h3 id="sqlite" tabindex="-1">SQLite <a class="header-anchor" href="#sqlite" aria-label="Permalink to &quot;SQLite&quot;">​</a></h3><ul><li><strong>Setup</strong>: Embedded, serverless, single-file database within the app.</li><li><strong>Resource Use</strong>: Minimal—runs on the VM’s existing 24 GB RAM and 4 cores. With Redis caching 99% of reads, SQLite handles ~1,990 operations/minute (~33/second), a tiny fraction of its tuned capacity (80,000 inserts/second, <a href="https://phiresky.github.io/blog/2020/sqlite-performance-tuning/" target="_blank" rel="noreferrer">SQLite Performance Tuning</a>).</li><li><strong>Cost</strong>: $0. No licensing, no server, no additional VMs required.</li><li><strong>Scaling</strong>: LiteFS adds replication in Phase 3 at no cost beyond the free tier’s resources.</li></ul><h3 id="postgresql" tabindex="-1">PostgreSQL <a class="header-anchor" href="#postgresql" aria-label="Permalink to &quot;PostgreSQL&quot;">​</a></h3><ul><li><strong>Setup</strong>: Standalone server process, typically on the same VM in Phase 1.</li><li><strong>Resource Use</strong>: Higher than SQLite—requires dedicated memory (e.g., 1-2 GB for buffers) and CPU for connection handling. At 100 req/s (Phase 1), it’s manageable, but at 100,000 RPM, connection pooling and read replicas would strain the free tier’s limits.</li><li><strong>Cost</strong>: $0 on the free VM initially, but scaling beyond one node (e.g., read replicas) demands paid resources (~$10/month per instance on AWS RDS or similar).</li><li><strong>Scaling</strong>: Vertical scaling works for Phase 1, but horizontal scaling (e.g., multi-node HA) incurs costs incompatible with the $0 goal.</li></ul><h3 id="mongodb" tabindex="-1">MongoDB <a class="header-anchor" href="#mongodb" aria-label="Permalink to &quot;MongoDB&quot;">​</a></h3><ul><li><strong>Setup</strong>: Document-based, requires a 3-node replica set for high availability (HA) in production.</li><li><strong>Resource Use</strong>: Heavy—each node needs ~1-2 GB RAM and significant disk I/O. A single-node setup fits the free tier but risks data loss; HA exceeds it, needing multiple VMs.</li><li><strong>Cost</strong>: $0 on one VM (not recommended for production), but $15-30/month for a 3-node cluster (e.g., MongoDB Atlas M10 tier at $5/node/month). Even self-hosted HA on paid VMs starts at $10-20/month.</li><li><strong>Scaling</strong>: Horizontal scaling is MongoDB’s strength, but the cost of additional nodes clashes with the project’s budget.</li></ul><h3 id="comparison-table" tabindex="-1">Comparison Table <a class="header-anchor" href="#comparison-table" aria-label="Permalink to &quot;Comparison Table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Database</th><th>Cost on Free Tier</th><th>Cost to Scale (100,000 RPM)</th><th>Resource Fit (24 GB, 4 cores)</th><th>HA Feasibility</th></tr></thead><tbody><tr><td>SQLite</td><td>$0</td><td>$0 (with LiteFS)</td><td>Excellent (minimal load)</td><td>Yes (Phase 3)</td></tr><tr><td>PostgreSQL</td><td>$0</td><td>$10-20/month (replicas)</td><td>Moderate (higher overhead)</td><td>No</td></tr><tr><td>MongoDB</td><td>$0 (single node)</td><td>$15-30/month (3 nodes)</td><td>Poor (HA exceeds tier)</td><td>No</td></tr></tbody></table><p><strong>Finding</strong>: SQLite is the only option that scales to 100,000 RPM at $0, thanks to its lightweight design and LiteFS.</p><h2 id="workload-and-optimization" tabindex="-1">Workload and Optimization <a class="header-anchor" href="#workload-and-optimization" aria-label="Permalink to &quot;Workload and Optimization&quot;">​</a></h2><h3 id="assumptions" tabindex="-1">Assumptions <a class="header-anchor" href="#assumptions" aria-label="Permalink to &quot;Assumptions&quot;">​</a></h3><ul><li><strong>Traffic</strong>: 100,000 RPM (1,666 req/s), with 1% writes (1,000 new URLs/minute) and 99% reads (99,000 redirects/minute).</li><li><strong>Caching</strong>: Redis handles 99% of reads (98,010 req/min), leaving ~990 reads and 1,000 writes (~33 ops/second) for the database.</li><li><strong>Request Size</strong>: 1 KB/request (URL data + headers), totaling 13.33 Mbps.</li></ul><h3 id="cost-saving-optimizations" tabindex="-1">Cost-Saving Optimizations <a class="header-anchor" href="#cost-saving-optimizations" aria-label="Permalink to &quot;Cost-Saving Optimizations&quot;">​</a></h3><ul><li><strong>Redis Caching</strong>: Offloads 99% of redirects, reducing database load to ~1% of total traffic. At $0 (running on the VM), it’s a cost-effective alternative to MongoDB’s read-heavy design.</li><li><strong>SQLite Tuning</strong>: WAL mode, synchronous normal, and memory mapping keep SQLite’s footprint tiny while hitting 80,000 inserts/second (<a href="https://news.ycombinator.com/item?id=35547819" target="_blank" rel="noreferrer">Hacker News</a>). No additional hardware needed.</li><li><strong>Single-Node Design</strong>: Phases 1-2 avoid multi-node complexity, fitting all components (Node.js, Redis, SQLite) on one VM. Phase 3’s LiteFS uses spare capacity for replication.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>Bit.ly’s 33M clicks/day (~23,000 RPM) with ~230 writes/minute suggests URL shorteners have low write loads, aligning with SQLite’s strengths (<a href="https://bitly.com/pages/statistics" target="_blank" rel="noreferrer">Bitly Stats Reference</a>).</li><li>Oracle’s 4 Gbps bandwidth supports ~2.4M RPM at 1 KB/request, far beyond the target.</li></ul><p><strong>Finding</strong>: Caching and tuning make 100,000 RPM feasible at $0, leveraging the free tier’s full potential.</p><h2 id="trade-offs" tabindex="-1">Trade-Offs <a class="header-anchor" href="#trade-offs" aria-label="Permalink to &quot;Trade-Offs&quot;">​</a></h2><ul><li><strong>SQLite</strong>: Sacrifices multi-node HA until Phase 3 (LiteFS), but caching mitigates downtime risks. Ideal for cost focus.</li><li><strong>PostgreSQL</strong>: Offers robust HA with paid replicas, but at $10-20/month, it’s overkill for this use case.</li><li><strong>MongoDB</strong>: Provides scalability and flexibility, but the $15-30/month HA cost and resource mismatch rule it out.</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>QuickLinker-ZeroRPM achieves $0/month costs by:</p><ol><li>Hosting on Oracle’s free tier (4 cores, 24 GB RAM, 4 Gbps).</li><li>Using SQLite with Redis caching, handling 100,000 RPM with ~33 ops/second.</li><li>Avoiding server-based databases (PostgreSQL, MongoDB) that incur scaling costs.</li></ol><p>This analysis confirms SQLite as the cost-efficient backbone, with LiteFS poised to address reliability in Phase 3—all within the free tier’s limits. PostgreSQL suits Phase 1’s simplicity, but MongoDB’s overhead makes it impractical.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>See how this plays out in:</p><ul><li><strong><a href="./../technical-architecture/phase-1/">Phase 1</a></strong>: SQLite implementation.</li><li><strong><a href="./../">References</a></strong>: Cited resources.</li></ul><hr><p><em>Last Updated: March 11, 2025</em></p>',38)]))}]]);export{s as __pageData,o as default};
